Item.method_code:
/*
    帳票マスタと開達書式IV用保存メソッド

    ・保存時にサインオフ画面を更新（保存/完了処理時に担当者の更新がかかり、サインオフ画面の更新が必要なため）
    ・改訂中時、保存の代わりに完了を実施
    ・改訂中時、公開へプロモート
*/
var inn = aras.IomInnovator;
const REREASED = "Release";
const INREVISION = "InRevision";

const thisType = this.itemTypeName;
var thisID = parent.thisItem.getID();
var thisConfigID = parent.thisItem.getProperty("config_id");


var ItemType = this.itemTypeName;
var relName = "";

if(ItemType == "h4_MQPage")
{
    relName = "h4_MQSingOff1";
}
else if(ItemType == "h4_ReqDoc")
{
    relName = "h4_ReqDoc SingOff1N";
}
else if(ItemType == "h4_Test_Result")
{
    relName = "h4_Test_Result SignOff";
}
else if(ItemType == "h4_ApprovalWFGroup")
{
    relName = "h4_ApprovalWFGroup_ApSignOff";
}
else if(ItemType == "h4_DATMaster")
{
    relName = "h4_DATMaster SingOff";
}
else if(ItemType == "h4_DATFormat")
{
    relName = "h4_DATFormat SingOff";
}
else if(ItemType == "h4_AppWFGroupForDATFormat")
{
    relName = "h4_AppWFGrForDATFormat SingOff";
}


if(parent.thisItem.getProperty("state","") == INREVISION)
{
    if (window.window.onDoneCommand)
    {
        //必ず処理後にタブ表示処理が来るように
        window.window.onDoneCommand().then(()=>{
            // 公開へプロモート
            var result = inn.newItem("Method", "h4_PromoteForClient");
            result.setProperty("configID",thisConfigID);
            result.setProperty("targetType", thisType);
            result.setProperty("newState", REREASED);
            result = result.apply();
            if (result.isError()) {
                aras.AlertError(result.getErrorString());
                return;
            }

            // h2_Top_DoneCliの流用
            // タブ表示の更新
            if (aras.getMostTopWindowWithAras(window).frames.relationships) {
                const iFramesCollection = aras.getMostTopWindowWithAras(window).frames.relationships.iframesCollection;
                for (const tabId in iFramesCollection) {
                if (Object.prototype.hasOwnProperty.call(iFramesCollection, tabId)) {
                        const relshipTypeNd = aras.getRelationshipType(tabId);
                        const relshipTypeName = aras.getItemProperty(relshipTypeNd.node, "name");
                        if (relshipTypeName === relName) {
                            const topWnd = aras.getMostTopWindowWithAras(window);
                            const queryString = {
                                db: parent.aras.getDatabase(), ITName: thisItem.getType(), relTypeID: tabId, itemID: thisItem.getId(), editMode: (document.isEditMode ? 1 : 0),
                                    tabbar: '1', toolbar: '1',
                                    where: 'tabview'
                            };
                            topWnd.relationships.relationshipsControl.reload(queryString);
                        }
                }
                }
            }// タブ更新ここまで
            //parent.onRefresh();
        })
    }
}
else
{
    if (window.window.onSaveCommand)
    {
        //必ず処理後にタブ表示処理が来るように
        window.window.onSaveCommand().then(()=>{
            // h2_Top_DoneCliの流用
            // タブ表示の更新
            if (aras.getMostTopWindowWithAras(window).frames.relationships) {
                const iFramesCollection = aras.getMostTopWindowWithAras(window).frames.relationships.iframesCollection;
                for (const tabId in iFramesCollection) {
                if (Object.prototype.hasOwnProperty.call(iFramesCollection, tabId)) {
                        const relshipTypeNd = aras.getRelationshipType(tabId);
                        const relshipTypeName = aras.getItemProperty(relshipTypeNd.node, "name");
                        if (relshipTypeName === relName) {
                            const topWnd = aras.getMostTopWindowWithAras(window);
                            const queryString = {
                                db: parent.aras.getDatabase(), ITName: thisItem.getType(), relTypeID: tabId, itemID: thisItem.getId(), editMode: (document.isEditMode ? 1 : 0),
                                    tabbar: '1', toolbar: '1',
                                    where: 'tabview'
                            };
                            topWnd.relationships.relationshipsControl.reload(queryString);
                        }
                }
                
                // h4_Table_SaveCliで実行していたタブ更新
                const relshipTypeNdWijmoUpdate = aras.getRelationshipType(tabId);
                const relshipTypeNameWijmoUpdate = aras.getItemProperty(relshipTypeNdWijmoUpdate.node, "name");
                if (relshipTypeNameWijmoUpdate === "h4_DATMaster Table" || relshipTypeNameWijmoUpdate === "h4_DMPMaster Table" || relshipTypeNameWijmoUpdate === "h4_MQWijimo") {
                    var topWndWijmoUpdate = aras.getMostTopWindowWithAras(window);
                    var queryStringWijmoUpdate = {
                        db: parent.aras.getDatabase(), ITName: thisItem.getType(), relTypeID: tabId, itemID: thisItem.getId(), editMode: (document.isEditMode ? 1 : 0),
                            tabbar: '1', toolbar: '1',
                            where: 'tabview'
                    };
                        topWndWijmoUpdate.relationships.relationshipsControl.reload(queryStringWijmoUpdate);
                }
                
                }
            }// タブ更新ここまで
        })
    }
}

return;
